<?php declare(strict_types=1);require __DIR__.'/../inc/db.php';require __DIR__.'/../inc/page.php';require_admin_role();$shop=$pdo->query('SELECT * FROM stores ORDER BY is_active DESC,id LIMIT 1')->fetch();if(!$shop)exit('No shop record exists.');if($_SERVER['REQUEST_METHOD']==='POST'){require_post_csrf();$pdo->beginTransaction();try{$pdo->exec('UPDATE stores SET is_active=0');$pdo->prepare('UPDATE stores SET name=?,address=?,phone=?,open_time=?,close_time=?,is_active=1 WHERE id=?')->execute([trim((string)$_POST['name']),trim((string)$_POST['address']),trim((string)$_POST['phone']),$_POST['open_time'],$_POST['close_time'],$shop['id']]);$pdo->commit();redirect('shop.php');}catch(Throwable $e){$pdo->rollBack();throw $e;}}page_start('Shop settings');?><main class="container py-4" style="max-width:760px"><h1 class="h3">Pickup shop</h1><p class="help-text">Customer flows use this one active pickup location.</p><form method="post" class="app-card p-4"><?=csrf_field()?><label class="form-label">Shop name</label><input name="name" class="form-control" value="<?=e($shop['name'])?>" required><label class="form-label mt-3">Address</label><textarea name="address" class="form-control" required><?=e($shop['address'])?></textarea><label class="form-label mt-3">Phone</label><input name="phone" class="form-control" value="<?=e($shop['phone'])?>"><div class="row g-3 mt-1"><div class="col"><label class="form-label">Opening time</label><input type="time" name="open_time" value="<?=e(substr($shop['open_time'],0,5))?>" class="form-control"></div><div class="col"><label class="form-label">Closing time</label><input type="time" name="close_time" value="<?=e(substr($shop['close_time'],0,5))?>" class="form-control"></div></div><button class="btn btn-purple mt-4">Save pickup shop</button></form></main><?php page_end();
